#!/usr/bin/env node
/* Builds data/bundle.js from the canonical JSON under config/ and lessons/.

   Questions no longer live here: they are extracted from the source PDF into
   data/questions.*.js by scripts/extract_bank.py and loaded a subtest at a
   time. This bundle carries the exam structure, the scoring tables and the
   lessons.

   Why this exists: index.html has to work when double-clicked, and browsers
   block fetch() on file:// URLs. A single <script> assignment loads everywhere
   -- file://, GitHub Pages, and the offline service worker cache alike.
   The JSON files stay the source of truth; validate.js fails if the bundle
   has drifted from them. */
'use strict';
const fs = require('fs');
const path = require('path');
const ROOT = path.resolve(__dirname, '..');

function readDir(dir) {
  const full = path.join(ROOT, dir);
  if (!fs.existsSync(full)) return [];
  return fs.readdirSync(full).filter(f => f.endsWith('.json')).sort()
    .map(f => ({ file: dir + '/' + f, json: JSON.parse(fs.readFileSync(path.join(full, f), 'utf8')) }));
}

function build() {
  const config = JSON.parse(fs.readFileSync(path.join(ROOT, 'config/test-config.json'), 'utf8'));
  const formats = JSON.parse(fs.readFileSync(path.join(ROOT, 'config/exam_formats.json'), 'utf8'));
  const scoring = JSON.parse(fs.readFileSync(path.join(ROOT, 'config/scoring.json'), 'utf8'));
  const composites = JSON.parse(fs.readFileSync(path.join(ROOT, 'config/composites.json'), 'utf8'));

  const lessons = [];
  for (const { file, json } of readDir('lessons')) {
    const list = Array.isArray(json) ? json : (json.lessons || []);
    list.forEach(l => lessons.push(Object.assign({ _file: file }, l)));
  }

  return { config, formats, scoring, composites, lessons };
}

function serialize(data) {
  return '/* GENERATED by tools/bundle.js -- do not edit.\n' +
    '   Source of truth: config/*.json and lessons/*.json\n' +
    '   Regenerate with: node tools/bundle.js  (validate.js checks freshness) */\n' +
    '(function (root) {\n  var DATA = ' + JSON.stringify(data) + ';\n' +
    '  if (typeof module === "object" && module.exports) module.exports = DATA;\n' +
    '  else root.ASVAB_DATA = DATA;\n' +
    '})(typeof self !== "undefined" ? self : this);\n';
}

function write() {
  const out = serialize(build());
  const dest = path.join(ROOT, 'data/bundle.js');
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  const prev = fs.existsSync(dest) ? fs.readFileSync(dest, 'utf8') : null;
  if (prev === out) return { changed: false, bytes: out.length, dest };
  fs.writeFileSync(dest, out);
  return { changed: true, bytes: out.length, dest };
}

module.exports = { build, serialize, write };

if (require.main === module) {
  const r = write();
  const d = build();
  console.log((r.changed ? 'wrote ' : 'up to date: ') + 'data/bundle.js (' + (r.bytes / 1024).toFixed(1) + ' KB)');
  console.log('  lessons: ' + d.lessons.length +
    ' | exam profiles: ' + (d.formats.profiles || []).length +
    ' | composite groups: ' + (d.composites.groups || []).length);
}
